OC.License={NOTIFICATION_TEMPLATE:'<div id="license_notification" title="{{title}}">  <div>    {{#each msgs}}    <p>      {{this}}    </p>    {{/each}}    <br/>    <p><a class="button" target="_blank" href="{{clickable_link}}">{{clickable_link_text}}</a></p>    <br/>    <p>{{time_remaining_msg}}</p>  </div>  <div style="display:flex">  <input id="license" type="text" placeholder="{{placeholder}}" style="flex:1 1 auto"/>  <button id="license_button">{{license_button_text}}</button>  </div></div>',showNotification:function(){this._template||(this._template=Handlebars.compile(this.NOTIFICATION_TEMPLATE));var e=this._template,i=this;$.get(OC.generateUrl("/license/graceperiod")).done(function(o){if(o&&!(o.apps<1)){var n="https://owncloud.com/try-enterprise/";o.demoKeyLink&&(n=o.demoKeyLink);var l=moment.relativeTimeThreshold("h"),a=moment.relativeTimeThreshold("m");moment.relativeTimeThreshold("h",25),moment.relativeTimeThreshold("m",90);var r=moment(1e3*o.end).fromNow(!0);moment.relativeTimeThreshold("h",l),moment.relativeTimeThreshold("m",a);var s=[t("core","You have enabled one or more Enterprise apps but your installation does not have a valid license yet."),t("core","A grace period of 24 hours has started to allow you to get going right away. Once the grace period ends, all Enterprise apps will become disabled unless you supply a valid license key."),t("core","To try the Enterprise apps, just start a 30-day demo and enter the provided license key below.")],c=$(e({title:t("core","Upgrade to Enterprise"),msgs:s,time_remaining_msg:t("core","Remaining time: {rtime}",{rtime:r}),clickable_link:n,clickable_link_text:t("core","Get your demo key"),placeholder:t("core","Enter license key"),license_button_text:t("core","Set new key")})).appendTo("body").ocdialog({modal:!0});i._initializeDialogEvents(c)}})},_initializeDialogEvents:function(e){e.on("ocdialogclose",function(){e.remove()}),e.find("#license_button").click(function(){var t=e.find("#license").val();$.post(OC.generateUrl("/license/license"),{licenseString:t}).done(function(){e.ocdialog("close")})})}},$(document).ready(function(){OC.License.showNotification()});